// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A planning-revision capture carries the four inputs of the LEO revision separately (feedback, filter and learned
 * filter revisions, provider generation), so that "only learned state differs" between two captures can be told apart
 * from a provider publication, which moves the LEO revision exactly like learned feedback. The LEO revision itself
 * keeps its value and meaning.
 */
class LmdbPlanningRevisionComponentsTest {

	@Test
	void aCaptureCarriesTheInputsOfItsLeoRevision(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				connection.add(connection.getValueFactory().createIRI("urn:components:s"),
						connection.getValueFactory().createIRI("urn:components:p"),
						connection.getValueFactory().createLiteral("o"));
			}
			LmdbTestUtil.awaitBackgroundMaintenance(store, 120, TimeUnit.SECONDS);
			LmdbEstimatorRuntime runtime = ((LmdbEvaluationStatistics) store.getSailStore()
					.getEvaluationStatistics()).estimatorRuntime();
			LmdbEstimatorRuntime.PlanningRevisions capture = runtime.capturePlanningRevisions();
			LmdbEstimatorRuntime.LearnedRevisions learned = capture.learned();
			assertNotNull(learned, "a capture carries its learned components");

			long recomputed = LmdbEstimatorRevisionSupport.mixRevision(0x4c454f5f52455649L, learned.feedback());
			recomputed = LmdbEstimatorRevisionSupport.mixRevision(recomputed, learned.filters());
			recomputed = LmdbEstimatorRevisionSupport.mixRevision(recomputed,
					learned.learnedFilters() < 0L ? 0L : learned.learnedFilters());
			recomputed = LmdbEstimatorRevisionSupport.mixRevision(recomputed, learned.providerGeneration())
					& Long.MAX_VALUE;
			long leo = recomputed;

			assertAll(
					() -> assertEquals(runtime.feedback().planningRevision(), learned.feedback()),
					() -> assertEquals(runtime.filters().planningRevision(), learned.filters()),
					() -> assertEquals(-1L, learned.learnedFilters(),
							"learned filter selectivity is absent in the default configuration"),
					() -> assertEquals(leo, capture.leoRevision(), "the LEO revision is the hash of its inputs"),
					() -> assertEquals(runtime.leoRevision(), capture.leoRevision(),
							"the LEO revision keeps its value"));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void onlyLearnedStateDiffersWhenNothingButALearnedComponentMoved() {
		LmdbPipelinePlanCache.Revision base = revision(1L, 2L, 10L, 20L, 0L, 5L, 7L, true);

		assertAll(
				() -> assertTrue(base.onlyLearnedStateDiffers(revision(1L, 2L, 11L, 20L, 0L, 5L, 7L, true)),
						"a feedback revision move"),
				() -> assertTrue(base.onlyLearnedStateDiffers(revision(1L, 2L, 10L, 21L, 0L, 5L, 7L, true)),
						"a filter revision move"),
				() -> assertFalse(base.onlyLearnedStateDiffers(base), "nothing differs"),
				() -> assertFalse(base.onlyLearnedStateDiffers(revision(9L, 2L, 11L, 20L, 0L, 5L, 7L, true)),
						"the data revision moved"),
				() -> assertFalse(base.onlyLearnedStateDiffers(revision(1L, 9L, 11L, 20L, 0L, 5L, 7L, true)),
						"the Frontier revision moved"),
				() -> assertFalse(base.onlyLearnedStateDiffers(revision(1L, 2L, 11L, 20L, 0L, 6L, 7L, true)),
						"a provider publication moved the generation"),
				() -> assertFalse(base.onlyLearnedStateDiffers(revision(1L, 2L, 11L, 20L, 0L, 5L, 8L, true)),
						"the predicate range version moved"),
				() -> assertFalse(base.onlyLearnedStateDiffers(revision(1L, 2L, 11L, 20L, 0L, 5L, 7L, false)),
						"adaptive evidence was switched"),
				() -> assertFalse(base.onlyLearnedStateDiffers(new LmdbPipelinePlanCache.Revision(
						new LmdbEstimatorRuntime.PlanningRevisions(1L, 2L, 99L, 98L), 7L, true)),
						"a capture without its components cannot be compared"));
	}

	private static LmdbPipelinePlanCache.Revision revision(long data, long frontier, long feedback, long filters,
			long learnedFilters, long generation, long predicateRangeVersion, boolean adaptive) {
		LmdbEstimatorRuntime.LearnedRevisions learned = new LmdbEstimatorRuntime.LearnedRevisions(feedback, filters,
				learnedFilters, generation);
		long leo = learned.leoRevision();
		return new LmdbPipelinePlanCache.Revision(new LmdbEstimatorRuntime.PlanningRevisions(data, frontier, leo,
				LmdbEstimatorRevisionSupport.learnedEvidenceRevision(data, leo, frontier), learned),
				predicateRangeVersion, adaptive);
	}
}
